(function(){"use strict";function toggleScrolled(){const selectBody=document.querySelector('body');const selectHeader=document.querySelector('#header');if(!selectHeader.classList.contains('scroll-up-sticky')&&!selectHeader.classList.contains('sticky-top')&&!selectHeader.classList.contains('fixed-top'))return;window.scrollY>100?selectBody.classList.add('scrolled'):selectBody.classList.remove('scrolled')}document.addEventListener('scroll',toggleScrolled);window.addEventListener('load',toggleScrolled);let lastScrollTop=0;window.addEventListener('scroll',function(){const selectHeader=document.querySelector('#header');if(!selectHeader.classList.contains('scroll-up-sticky'))return;let scrollTop=window.pageYOffset||document.documentElement.scrollTop;if(scrollTop>lastScrollTop&&scrollTop>selectHeader.offsetHeight){selectHeader.style.setProperty('position','sticky','important');selectHeader.style.top=`-${selectHeader.offsetHeight+50}px`}else if(scrollTop>selectHeader.offsetHeight){selectHeader.style.setProperty('position','sticky','important');selectHeader.style.top="0"}else{selectHeader.style.removeProperty('top');selectHeader.style.removeProperty('position')}lastScrollTop=scrollTop});const mobileNavToggleBtn=document.querySelector('.mobile-nav-toggle');function mobileNavToogle(){document.querySelector('body').classList.toggle('mobile-nav-active');mobileNavToggleBtn.classList.toggle('bi-list');mobileNavToggleBtn.classList.toggle('bi-x')}mobileNavToggleBtn.addEventListener('click',mobileNavToogle);document.querySelectorAll('#navmenu a').forEach(navmenu=>{navmenu.addEventListener('click',()=>{if(document.querySelector('.mobile-nav-active')){mobileNavToogle()}})});document.querySelectorAll('.navmenu .toggle-dropdown').forEach(navmenu=>{navmenu.addEventListener('click',function(e){e.preventDefault();this.parentNode.classList.toggle('active');this.parentNode.nextElementSibling.classList.toggle('dropdown-active');e.stopImmediatePropagation()})});const preloader=document.querySelector('#preloader');if(preloader){window.addEventListener('load',()=>{preloader.remove()})}let scrollTop=document.querySelector('.scroll-top');function toggleScrollTop(){if(scrollTop){window.scrollY>100?scrollTop.classList.add('active'):scrollTop.classList.remove('active')}}scrollTop.addEventListener('click',(e)=>{e.preventDefault();window.scrollTo({top:0,behavior:'smooth'})});window.addEventListener('load',toggleScrollTop);document.addEventListener('scroll',toggleScrollTop);function aosInit(){AOS.init({duration:600,easing:'ease-in-out',once:true,mirror:false})}window.addEventListener('load',aosInit);function initSwiper(){document.querySelectorAll(".init-swiper").forEach(function(swiperElement){let config=JSON.parse(swiperElement.querySelector(".swiper-config").innerHTML.trim());if(swiperElement.classList.contains("swiper-tab")){initSwiperWithCustomPagination(swiperElement,config)}else{new Swiper(swiperElement,config)}})}window.addEventListener("load",initSwiper);const glightbox=GLightbox({selector:'.glightbox'});const NewsManager={carouselMaxItems:3,latestNewsMaxItems:3,blogPageMaxItems:6,currentPage:1,itemsPerPage:6,newsItems:[{id:9,title:"RAB Leads Harmonization of Irrigation Management Manuals under the OMIS Project",excerpt:"The Rwanda Agriculture and Animal Resources Development Board (RAB), in collaboration with HoReCo and YEAN under the OMIS Project",date:"2026-05-08",author:"Alexis Nyandwi",category:"HoReCo ",image:"assets/img/blog/blog-9.jpeg",detailUrl:"blog-details-9.html"},{id:8,title:"KABOKU Cooperative Farmers Double Maize Yields Through HoReCo Support Under OMIS Project",excerpt:"Farmers of KABOKU Cooperative in Kagitumba Sector, Nyagatare District, are celebrating a major milestone in maize production after increasing yields from an average of 3 tonnes per hectare to around 8 tonnes per hectare in Season 2026A",date:"2026-04-23",author:"Alexis Nyandwi",category:"HoReCo",image:"assets/img/blog/blog-8.jpeg",detailUrl:"blog-details-8.html"},{id:1,title:"HoReCo Capacity Building Program Strengthens Reporting and Coordination for OMIS Project Implementation",excerpt:"HoReCo successfully convened District Project Coordinators under the OMIS Project for training aimed at strengthening reporting systems and enhancing project implementation.",date:"2026-04-17",author:"Alexis Nyandwi",category:"OMIS",image:"assets/img/blog/blog-1.jpeg",detailUrl:"blog-details-1.html"},{id:2,title:"Validation of Quarterly Report for Lot 2 under the OMIS Project in Huye District",excerpt:"Successful validation of quarterly report for Lot 2 under the OMIS Project in Huye District, marking another milestone in project implementation.",date:"2026-03-31",author:"Alexis Nyandwi",category:"OMMIS",image:"assets/img/blog/blog-2.jpeg",detailUrl:"blog-details-2.html"},{id:3,title:"RAB Evaluation Mission Highlights Performance Review of ETI Mpanga and Nasho GFI Irrigation Schemes under HoReCo Management",excerpt:"RAB Evaluation Mission highlights performance review of ETI Mpanga and Nasho GFI Irrigation Schemes under HoReCo Management.",date:"2026-03-11",author:"Alexis Nyandwi",category:"OMIS",image:"assets/img/blog/blog-3.jpeg",detailUrl:"blog-details-3.html"},{id:5,title:"High-Level Delegation Visits ETI Mpanga Irrigation Scheme Ahead of Official Handover",excerpt:"the ETI Mpanga Irrigation Scheme in Kirehe District hosted a high-level official visit led by Hon. Telesphore Ndabamenye, Minister of Agriculture and Animal Resources (MINAGRI), and Dr. Jimmy Gasore, Minister of Infrastructure. They were accompanied by Pudence Rubingisa, Governor of Eastern Province, H.E. Mridu Pawan Das, High Commissioner of India to Rwanda, together with other distinguished guests.",date:"2026-03-25",author:"Alexis Nyandwi",category:"OMIS",image:"assets/img/blog/blog-5.jpeg",detailUrl:"blog-details-5.html"},{id:4,title:"Dr. Uwamahoro Commends HoReCo Farm for Excellence in Potato Seed Production*",excerpt:"Acting Director General of the Rwanda Agriculture and Animal Resources Board (RAB), visited the RAB/Kinigi site to evaluate the performance of HoReCo Farm, one of the key partners supporting Rwanda's agricultural development agenda.",date:"2026-01-22",author:"Alexis Nyandwi",category:"OMIS",image:"assets/img/blog/blog-4.jpeg",detailUrl:"blog-details-4.html"},{id:6,title:"SNV Rwanda Delegation Visits YEA-R Project Sites in Karongi District",excerpt:"Today, HoReCo Rwanda welcomed a delegation from SNV Rwanda, led by Country Director Eleanor Hartzell, to the YEA-R Project sites in Karongi District. The visit underscored the strong partnership and shared commitment to expanding inclusive and sustainable economic opportunities for young women, men, and persons with disabilities in Rwanda's horticulture sector.",date:"2025-12-09",author:"Alexis Nyandwi",category:"SNV",image:"assets/img/blog/blog-6.jpeg",detailUrl:"blog-details-6.html"}],sortNewsByDate(){this.newsItems.sort((a,b)=>{const dateA=new Date(a.date);const dateB=new Date(b.date);const yearDiff=dateB.getFullYear()-dateA.getFullYear();if(yearDiff!==0)return yearDiff;const monthDiff=dateB.getMonth()-dateA.getMonth();if(monthDiff!==0)return monthDiff;return dateB.getDate()-dateA.getDate()})},formatDate(dateString){const date=new Date(dateString);const options={year:'numeric',month:'long',day:'numeric'};return date.toLocaleDateString('en-US',options)},getDayAndMonth(dateString){const date=new Date(dateString);const day=date.getDate();const months=['January','February','March','April','May','June','July','August','September','October','November','December'];const month=months[date.getMonth()];return{day,month}},addNewsItem(newsItem){newsItem.id=Date.now();this.newsItems.push(newsItem);this.sortNewsByDate();this.resetPagination();this.updateAllNewsSections();this.updateAllSectionsWithLatestNews()},updateAllSectionsWithLatestNews(){this.updateSlideshow();this.updateLatestNewsSection();this.updateBlogPage()},updateSlideshow(){const slides=document.querySelectorAll('.slide');const dots=document.querySelectorAll('.dot');const latestNews=this.newsItems.slice(0,3);if(slides.length===0)return;latestNews.forEach((news,index)=>{if(slides[index]){const slide=slides[index];const isActive=index===0?'active':'';slide.classList.toggle('active',isActive);slide.querySelector('img').src=news.image;slide.querySelector('img').alt=news.title;slide.querySelector('h3').textContent=news.title;slide.querySelector('p').textContent=news.excerpt;slide.querySelector('.btn-cta').href=news.detailUrl}if(dots[index]){dots[index].classList.toggle('active',index===0)}});currentSlideIndex=1;resetAutoSlide()},updateLatestNewsSection(){const latestNewsContainer=document.querySelector('#recent-posts .row');if(!latestNewsContainer)return;const latestNews=this.newsItems.slice(0,3);latestNewsContainer.innerHTML='';latestNews.forEach((news,index)=>{const{day,month}=this.getDayAndMonth(news.date);const delay=(index+1)*100;const newsHTML=`<div class="col-xl-4 col-md-6"><div class="post-item position-relative h-100" data-aos="fade-up" data-aos-delay="${delay}"><div class="post-img position-relative overflow-hidden"><img src="${news.image}" class="img-fluid" alt=""><span class="post-date">${month} ${day}</span></div><div class="post-content d-flex flex-column"><h3 class="post-title">${news.title}</h3><div class="meta d-flex align-items-center"><div class="d-flex align-items-center"><i class="bi bi-person"></i> <span class="ps-2">${news.author}</span></div><span class="px-3 text-black-50">/</span><div class="d-flex align-items-center"><i class="bi bi-folder2"></i> <span class="ps-2">${news.category}</span></div></div><hr><a href="${news.detailUrl}" class="readmore stretched-link"><span>Read More</span><i class="bi bi-arrow-right"></i></a></div></div></div>`;latestNewsContainer.insertAdjacentHTML('beforeend',newsHTML)})},updateLatestNews(){const latestNewsContainer=document.querySelector('#recent-posts .row');if(!latestNewsContainer)return;const latestNewsItems=this.newsItems.slice(0,this.latestNewsMaxItems);const existingPosts=latestNewsContainer.querySelectorAll('.col-xl-4, .col-md-6');latestNewsItems.forEach((item,index)=>{const{day,month}=this.getDayAndMonth(item.date);if(existingPosts[index]){const post=existingPosts[index];const postItem=post.querySelector('.post-item');const delay=(index+1)*100;postItem.setAttribute('data-aos-delay',delay);post.querySelector('.post-img img').src=item.image;post.querySelector('.post-date').textContent=`${month} ${day}`;post.querySelector('.post-title').textContent=item.title;post.querySelector('.meta').innerHTML=`<div class="d-flex align-items-center"><i class="bi bi-person"></i> <span class="ps-2">${item.author}</span></div><span class="px-3 text-black-50">/</span><div class="d-flex align-items-center"><i class="bi bi-folder2"></i> <span class="ps-2">${item.category}</span></div>`;post.querySelector('.readmore').href=item.detailUrl}})},updateBlogPage(){const blogContainer=document.querySelector('#blog-posts-2 .row');if(!blogContainer)return;const startIndex=(this.currentPage-1)*this.itemsPerPage;const endIndex=startIndex+this.itemsPerPage;const paginatedItems=this.newsItems.slice(startIndex,endIndex);blogContainer.innerHTML='';paginatedItems.forEach((item,index)=>{const{day,month}=this.getDayAndMonth(item.date);const articleHTML=`<div class="col-lg-4" data-aos="fade-up" data-aos-delay="${index*100}"><article class="position-relative h-100"><div class="post-img position-relative overflow-hidden"><img src="${item.image}" class="img-fluid" alt=""></div><div class="meta d-flex align-items-end"><span class="post-date"><span>${day}</span>${month}</span><div class="d-flex align-items-center"><i class="bi bi-person"></i> <span class="ps-2">${item.author}</span></div><span class="px-3 text-black-50">/</span><div class="d-flex align-items-center"><i class="bi bi-folder2"></i> <span class="ps-2">${item.category}</span></div></div><div class="post-content d-flex flex-column"><h3 class="post-title">${item.title}</h3><a href="${item.detailUrl}" class="readmore stretched-link"><span>Read More</span><i class="bi bi-arrow-right"></i></a></div></article></div>`;blogContainer.insertAdjacentHTML('beforeend',articleHTML)});this.updatePagination()},updatePagination(){const paginationContainer=document.querySelector('#pagination-container');if(!paginationContainer)return;const totalPages=2;paginationContainer.innerHTML='';const prevLi=document.createElement('li');prevLi.innerHTML=`<a href="#" ${this.currentPage===1?'class="disabled"':''}><i class="bi bi-chevron-left"></i></a>`;paginationContainer.appendChild(prevLi);for(let i=1;i<=totalPages;i++){const pageLi=document.createElement('li');pageLi.innerHTML=`<a href="#" ${i===this.currentPage?'class="active"':''}>${i}</a>`;paginationContainer.appendChild(pageLi)}const nextLi=document.createElement('li');nextLi.innerHTML=`<a href="#" ${this.currentPage===totalPages?'class="disabled"':''}><i class="bi bi-chevron-right"></i></a>`;paginationContainer.appendChild(nextLi);this.attachPaginationHandlers()},attachPaginationHandlers(){const paginationContainer=document.querySelector('#pagination-container');if(!paginationContainer)return;paginationContainer.addEventListener('click',(e)=>{e.preventDefault();const target=e.target.closest('a');if(!target||target.classList.contains('disabled'))return;const totalPages=2;if(target.querySelector('.bi-chevron-left')){if(this.currentPage>1){this.goToPage(this.currentPage-1)}}else if(target.querySelector('.bi-chevron-right')){if(this.currentPage<totalPages){this.goToPage(this.currentPage+1)}}else if(target.textContent&&!isNaN(parseInt(target.textContent))){const pageNumber=parseInt(target.textContent);if(pageNumber>=1&&pageNumber<=totalPages){this.goToPage(pageNumber)}}})},goToPage(pageNumber){const totalPages=2;if(pageNumber<1||pageNumber>totalPages)return;this.currentPage=pageNumber;this.updateBlogPage();const blogSection=document.querySelector('#blog-posts-2');if(blogSection){blogSection.scrollIntoView({behavior:'smooth',block:'start'})}},updateAllNewsSections(){this.updateCarousel();this.updateLatestNews();this.updateBlogPage()},resetPagination(){this.currentPage=1},init(){this.sortNewsByDate();if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{this.updateAllNewsSections();this.updateAllSectionsWithLatestNews()})}else{this.updateAllNewsSections();this.updateAllSectionsWithLatestNews()}}};NewsManager.init();window.NewsManager=NewsManager;window.addTestNews=function(){const newNewsItem={title:"New HoReCo Initiative Launches Digital Agriculture Platform",excerpt:"HoReCo introduces cutting-edge digital platform to revolutionize farming practices and increase agricultural productivity across Rwanda.",date:new Date().toISOString().split('T')[0],author:"HoReCo Team",category:"Innovation",image:"assets/img/blog/blog-1.jpeg",detailUrl:"#"};NewsManager.addNewsItem(newNewsItem);console.log('New news item added! Latest news is now first in all sections.')};window.addTestNewsWithDate=function(year,month,day){const date=new Date(year,month-1,day);const newNewsItem={title:`Test News for ${date.toLocaleDateString()}`,excerpt:`This is a test news item created for ${date.toLocaleDateString()} to verify latest-first sorting system works correctly.`,date:date.toISOString().split('T')[0],author:"Test System",category:"Testing",image:"assets/img/blog/blog-2.jpeg",detailUrl:"#"};NewsManager.addNewsItem(newNewsItem);console.log(`Added test news for ${date.toLocaleDateString()}. It should now appear first in all sections.`)};let currentSlideIndex=1;let slideInterval;function showSlide(n){const slides=document.getElementsByClassName('slide');const dots=document.getElementsByClassName('dot');if(n>slides.length){currentSlideIndex=1}if(n<1){currentSlideIndex=slides.length}for(let i=0;i<slides.length;i++){slides[i].classList.remove('active')}for(let i=0;i<dots.length;i++){dots[i].classList.remove('active')}slides[currentSlideIndex-1].classList.add('active');dots[currentSlideIndex-1].classList.add('active')}function changeSlide(n){currentSlideIndex+=n;showSlide(currentSlideIndex);resetAutoSlide()}function currentSlide(n){currentSlideIndex=n;showSlide(currentSlideIndex);resetAutoSlide()}function autoSlide(){currentSlideIndex++;showSlide(currentSlideIndex)}function startAutoSlide(){slideInterval=setInterval(autoSlide,3000)}function resetAutoSlide(){clearInterval(slideInterval);startAutoSlide()}document.addEventListener('DOMContentLoaded',function(){showSlide(currentSlideIndex);startAutoSlide()});console.log('News Management System initialized!');console.log('To add a test news item, run: addTestNews()');console.log('To add a custom news item, run: NewsManager.addNewsItem({title, excerpt, date, author, category, image, detailUrl})')})();
